const assert=require('node:assert/strict'),{spawn}=require('node:child_process'),{once}=require('node:events'),net=require('node:net');
const {setTimeout:delay}=require('node:timers/promises'),{chromium}=require(process.env.PLAYWRIGHT_MODULE||'playwright');
const fs=require('node:fs/promises'),path=require('node:path');
const png=Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAYAAABytg0kAAAAEUlEQVR4nGOQs4n6D8IMMAYAN7wGzYgpkEMAAAAASUVORK5CYII=','base64');
async function eventually(check,label){const until=Date.now()+12000;while(Date.now()<until){if(await check())return;await delay(40)}throw Error('Timed out: '+label)}
async function server(){
 const socket=net.createServer();socket.listen(0,'127.0.0.1');await once(socket,'listening');const port=socket.address().port;await new Promise(r=>socket.close(r));
 const env={...process.env};for(const key of Object.keys(env))if(key.startsWith('FAMILY_'))delete env[key];
 const launch=`import app,runpy,sys
review_count=0
def model(messages,*args,**kwargs):
    global review_count
    review_count+=1
    teacher=any('synthetic-teacher' in str(m.get('content','')) for m in messages)
    item=dict(label='第1题',question='虚构第1题：选择A、B或C',student_answer='C',answer='教师参考：B' if teacher else 'AI推导：C',judgment='incorrect' if teacher else 'correct',error_reason='与教师参考不同' if teacher else '',possible_cause='原因待孩子解释' if teacher else '',steps='先独立重答，再核对参考' if teacher else '',uncertainty='')
    note=next((x.get('text','') for m in messages if isinstance(m.get('content'),list) for x in m['content'] if x.get('type')=='text' and x.get('text','').startswith('原作答家长说明')), '')
    if '虚构甲卷' in note or '虚构乙卷' in note:
        paper='甲' if '虚构甲卷' in note else '乙'
        assert ('synthetic-teacher-'+paper+'.txt') in str(messages), 'matching teacher required'
        assert ('synthetic-teacher-'+('乙' if paper=='甲' else '甲')+'.txt') not in str(messages), 'other teacher must not mix'
        assert sum(x.get('type')=='image_url' for m in messages if isinstance(m.get('content'),list) for x in m['content'])==6, 'six selected answer pages'
        return dict(items=[item],coverage=paper+'卷第1题；第2、3题未检查，不能称整卷已核对',comparison='仅此卷教师参考，不影响另一卷')
    return dict(items=[item],coverage='虚构检查第%d轮；仅按明确题号比较，原题要求仍待核对'%review_count,comparison='补充老师参考后，第1题需订正；初检缺少老师依据。' if teacher else '初检尚无教师依据。')
app.family_llm._chat_json=model
sys.argv=['demo.py','--port',sys.argv[1]]
runpy.run_path('demo.py',run_name='__main__')`;
 const child=spawn(process.env.FAMILY_TEST_PYTHON||'python3',['-c',launch,String(port)],{cwd:__dirname,env,stdio:['ignore','pipe','pipe']});let error='';child.stdout.resume();child.stderr.on('data',b=>error+=b);
 const url='http://127.0.0.1:'+port+'/',stop=async()=>{if(child.exitCode!==null||child.signalCode!==null)return;const exited=once(child,'exit');child.kill('SIGINT');await Promise.race([exited,delay(2500)]);if(child.exitCode===null&&child.signalCode===null){child.kill('SIGKILL');await exited}};
 try{await eventually(async()=>{if(child.exitCode!==null)throw Error(error||'Demo exited');try{return(await fetch(url,{signal:AbortSignal.timeout(400)})).ok}catch{return false}},'synthetic server');return{url,stop}}catch(e){await stop();throw e}
}
