  await p.locator('#taskForm [name=note]').fill('虚构乙卷，第1—6页；题号1、2、3');await p.locator('#saveTaskFeedback').click();await eventually(async()=>/反馈已保存/.test(await p.locator('#taskFeedbackStatus').innerText()),'second paper saved');state=await read();
